'use client';

import { createContext, lazy, Suspense, useCallback, useContext, useEffect, useId, useMemo, useRef, useState, type MouseEvent, type ReactNode } from 'react';
import { readSourceURL, writeSourceURL, type SourceRequest } from '../../source-explorer/index.js';

const Explorer = lazy(() => import('./explorer.js'));
const SourceContext = createContext<{
  open: (request: SourceRequest) => void;
  register: (id: string, request: SourceRequest) => () => void;
} | null>(null);

export type SourceExplorerProviderProps = {
  children: ReactNode;
  /** Manifest generated by the host site. Snapshot asset URLs resolve relative to it. */
  manifestUrl?: string;
  /** Pass the router pathname so client-side page changes reset the drawer. */
  navigationKey?: string;
  /** Optional reading anchors to preserve position when the layout resizes. */
  scrollAnchorSelector?: string;
};

export function SourceExplorerProvider({
  children,
  manifestUrl = '/source-examples/manifest.json',
  navigationKey,
  scrollAnchorSelector,
}: SourceExplorerProviderProps) {
  const [request, setRequest] = useState<SourceRequest | null>(null);
  const [references, setReferences] = useState<Map<string, SourceRequest>>(() => new Map());
  const lastRequest = useRef<SourceRequest | null>(null);
  const ownsHistoryEntry = useRef(false);

  useEffect(() => {
    lastRequest.current = null;
    const sync = () => {
      ownsHistoryEntry.current = false;
      const next = readSourceURL(new URL(window.location.href));
      if (next) lastRequest.current = next;
      setRequest(next);
    };
    sync();
    window.addEventListener('popstate', sync);
    return () => window.removeEventListener('popstate', sync);
  }, [navigationKey]);

  const open = useCallback((next: SourceRequest) => {
    const url = writeSourceURL(new URL(window.location.href), next);
    if (readSourceURL(new URL(window.location.href))) {
      window.history.replaceState(window.history.state, '', url);
    } else {
      window.history.pushState(window.history.state, '', url);
      ownsHistoryEntry.current = true;
    }
    lastRequest.current = next;
    setRequest(next);
  }, []);

  const navigate = useCallback((next: SourceRequest) => {
    window.history.replaceState(window.history.state, '', writeSourceURL(new URL(window.location.href), next));
    lastRequest.current = next;
    setRequest(next);
  }, []);

  const close = useCallback(() => {
    if (ownsHistoryEntry.current) {
      ownsHistoryEntry.current = false;
      // popstate closes the drawer; don't allow a reopen to race the pending Back.
      window.history.back();
    } else {
      setRequest(null);
      window.history.replaceState(window.history.state, '', writeSourceURL(new URL(window.location.href), null));
    }
  }, []);

  const register = useCallback((id: string, value: SourceRequest) => {
    setReferences((previous) => new Map(previous).set(id, value));
    return () => {
      setReferences((previous) => {
        const next = new Map(previous);
        next.delete(id);
        return next;
      });
    };
  }, []);
  const context = useMemo(() => ({ open, register }), [open, register]);
  const defaultRequest = references.values().next().value as SourceRequest | undefined;
  const available = request ?? lastRequest.current ?? defaultRequest;

  return (
    <SourceContext.Provider value={context}>
      {children}
      {available && <button type="button" className="source-launcher" aria-label={request ? 'Thu source code' : 'Mở source code'}
        aria-expanded={!!request} aria-controls={request ? 'source-explorer' : undefined}
        onClick={() => request ? close() : open(lastRequest.current ?? defaultRequest ?? available)}>
        <svg width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
          <path d="m6 5-4 5 4 5M14 5l4 5-4 5M12 3 8 17" />
        </svg>
        <span>{request ? 'Thu source' : 'Source code'}</span>
        <span aria-hidden="true">{request ? '→' : '←'}</span>
      </button>}
      {request && <Suspense fallback={null}>
        <Explorer request={request} onNavigate={navigate} onClose={close}
          manifestUrl={manifestUrl} scrollAnchorSelector={scrollAnchorSelector} />
      </Suspense>}
    </SourceContext.Provider>
  );
}

export type SourceRefProps = SourceRequest & {
  children?: ReactNode;
  variant?: 'inline' | 'button';
};

export function SourceRef({ children, variant = 'inline', ...request }: SourceRefProps) {
  const context = useContext(SourceContext);
  const id = useId();
  const register = context?.register;
  const { project, snapshot, file, region, lines } = request;
  useEffect(() => register?.(id, { project, snapshot, file, region, lines }), [register, id, project, snapshot, file, region, lines]);
  const href = writeSourceURL(new URL('https://source.invalid/'), request).search;
  function handleClick(event: MouseEvent<HTMLAnchorElement>) {
    if (!context || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    context.open(request);
  }
  return (
    <a href={href} onClick={handleClick} className={`source-ref source-ref--${variant}`} aria-haspopup="dialog">
      <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
        <path d="m6 5-4 5 4 5M14 5l4 5-4 5M12 3 8 17" />
      </svg>
      <span>{children ?? request.file ?? 'Mở source ví dụ'}</span>
      <span className="source-ref-arrow" aria-hidden="true">↗</span>
    </a>
  );
}
